import random, time, requests

def get_com_backoff(url, headers, params=None, tentativas=6):
    for n in range(tentativas):
        r = requests.get(url, headers=headers, params=params, timeout=60)
        if r.status_code != 429:
            r.raise_for_status()
            return r.json()
        time.sleep(min(60, 2 ** n) + random.random())  # backoff exponencial com jitter
    raise RuntimeError('429 persistente: reduza a concorrência')
